theorem ProbabilityTheory.IsUniform.extracted_1.{uS, uΩ} {Ω : Type uΩ} {S : Type uS} [mΩ : MeasurableSpace Ω]
  {X : Ω → S} {μ : Measure Ω} [inst : MeasurableSpace S] [inst_1 : DiscreteMeasurableSpace S] {H : Finset S}
  (h : IsUniform (↑H) X μ) (hX : Measurable X) {s : S} (hs : s ∈ H) : μ univ = μ (X ⁻¹' (↑H)ᶜ) + μ (X ⁻¹' ↑H) := sorry

theorem ProbabilityTheory.IsUniform.extracted_1.{uS, uΩ} {Ω : Type uΩ} {S : Type uS} [mΩ : MeasurableSpace Ω]
  {X : Ω → S} {μ : Measure Ω} [inst : MeasurableSpace S] [inst_1 : DiscreteMeasurableSpace S] {H : Finset S}
  (h : IsUniform (↑H) X μ) (hX : Measurable X) {s : S} (hs : s ∈ H) : μ (X ⁻¹' ↑H) = ∑ x ∈ H, μ (X ⁻¹' {x}) := sorry

theorem ProbabilityTheory.IsUniform.extracted_1.{uS, uΩ} {Ω : Type uΩ} {S : Type uS} [mΩ : MeasurableSpace Ω]
  {X : Ω → S} {μ : Measure Ω} [inst : MeasurableSpace S] [inst_1 : DiscreteMeasurableSpace S] {H : Finset S}
  (h : IsUniform (↑H) X μ) (hX : Measurable X) {s : S} (hs : s ∈ H) (x : S) (hx : x ∈ H) : x ∈ ↑H := sorry

theorem ProbabilityTheory.IsUniform.extracted_1.{uT, uS, uΩ} {Ω : Type uΩ} {S : Type uS} {T : Type uT}
  [mΩ : MeasurableSpace Ω] {X : Ω → S} {μ : Measure Ω} {H : Finset S} (h : IsUniform (↑H) X μ) {f : S → T}
  (hf : Injective f) (x : S) (hx : x ∈ H) (y : S) (hy : y ∈ H) (z : S) : f ⁻¹' {f z} = {z} := sorry

theorem ProbabilityTheory.IsUniform.extracted_1.{uT, uS, uΩ} {Ω : Type uΩ} {S : Type uS} {T : Type uT}
  [mΩ : MeasurableSpace Ω] {X : Ω → S} {μ : Measure Ω} {H : Finset S} (h : IsUniform (↑H) X μ) {f : S → T}
  (hf : Injective f) (x : S) (hx : x ∈ H) (y : S) (hy : y ∈ H) (A : ∀ (z : S), f ⁻¹' {f z} = {z}) :
  μ (f ∘ X ⁻¹' {f x}) = μ (f ∘ X ⁻¹' {f y}) := sorry
